package io.infranexum.server.dcim.cli;
import io.infranexum.server.InfraNexumServerApplication;import java.io.PrintWriter;import java.util.Arrays;import org.springframework.boot.WebApplicationType;import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.context.ConfigurableApplicationContext;
/** Non-Web entry point for the Server-owned PGM-07-E05 CLI. */
public final class DcimPhysicalCliApplication {private DcimPhysicalCliApplication(){}public static void main(String[] args){int d=index(args,"--");if(d<0){System.err.println("usage: java ... DcimPhysicalCliApplication [Spring options] -- dcim physical ...");System.exit(DcimPhysicalCli.EXIT_USAGE);return;}try(ConfigurableApplicationContext c=new SpringApplicationBuilder(InfraNexumServerApplication.class).web(WebApplicationType.NONE).properties("spring.main.banner-mode=off").run(Arrays.copyOfRange(args,0,d))){System.exit(c.getBean(DcimPhysicalCli.class).run(Arrays.copyOfRange(args,d+1,args.length),new PrintWriter(System.out,true),new PrintWriter(System.err,true)));}}private static int index(String[] a,String x){for(int i=0;i<a.length;i++)if(x.equals(a[i]))return i;return -1;}}
